svg.script:
(function () {
  var NS = "http://www.w3.org/2000/svg";
  var CELL = 24, COLS = 20, ROWS = 20;
  var gEnt = document.getElementById("entities");
  var elScore = document.getElementById("score");
  var elBest = document.getElementById("best");
  var elOver = document.getElementById("over");
  var elPause = document.getElementById("pause");
  var elStart = document.getElementById("start");
  var elFinal = document.getElementById("finalScore");
  var snake, dir, queue, food, score, speed, timer, dead, paused, started;
  var best = 0;
  try { best = parseInt(localStorage.getItem("snake-best") || "0", 10) || 0; } catch (e) {}
  elBest.textContent = best;

  function mk(tag, attrs) {
    var el = document.createElementNS(NS, tag);
    for (var k in attrs) el.setAttribute(k, attrs[k]);
    return el;
  }
  function reset() {
    snake = [{x:10,y:10},{x:9,y:10},{x:8,y:10}];
    dir = {x:1,y:0}; queue = [];
    score = 0; speed = 150; dead = false; paused = false;
    elScore.textContent = "0";
    elOver.setAttribute("opacity", "0");
    elPause.setAttribute("opacity", "0");
    placeFood(); draw();
  }
  function placeFood() {
    do {
      food = { x: Math.floor(Math.random()*COLS), y: Math.floor(Math.random()*ROWS) };
    } while (snake.some(function (s) { return s.x===food.x && s.y===food.y; }));
  }
  function draw() {
    while (gEnt.firstChild) gEnt.removeChild(gEnt.firstChild);
    var f = mk("circle", { cx: food.x*CELL+CELL/2, cy: food.y*CELL+CELL/2, r: 8, fill: "#ff7b72", filter: "url(#g)" });
    gEnt.appendChild(f);
    for (var i = snake.length-1; i >= 0; i--) {
      var s = snake[i];
      var r = mk("rect", { x: s.x*CELL+2, y: s.y*CELL+2, width: CELL-4, height: CELL-4, rx: 6, fill: i===0 ? "#7ee787" : "url(#skin)" });
      if (i===0) r.setAttribute("filter", "url(#g)");
      gEnt.appendChild(r);
    }
  }
  function step() {
    if (queue.length) { var nd = queue.shift(); if (nd.x !== -dir.x || nd.y !== -dir.y) dir = nd; }
    var head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };
    if (head.x < 0 || head.y < 0 || head.x >= COLS || head.y >= ROWS ||
        snake.some(function (s) { return s.x===head.x && s.y===head.y; })) { die(); return; }
    snake.unshift(head);
    if (head.x===food.x && head.y===food.y) {
      score += 10;
      elScore.textContent = score;
      if (speed > 70) speed -= 4;
      placeFood();
    } else { snake.pop(); }
    draw();
  }
  function loop() { step(); if (!dead && !paused) timer = setTimeout(loop, speed); }
  function die() {
    dead = true;
    if (score > best) { best = score; elBest.textContent = best; try { localStorage.setItem("snake-best", String(best)); } catch (e) {} }
    elFinal.textContent = "得分 " + score + (score>=best && score>0 ? " · 新纪录!" : "");
    elOver.setAttribute("opacity", "1");
  }
  function startOrRestart() {
    if (!started) { started = true; elStart.setAttribute("opacity", "0"); }
    reset(); loop();
  }
  function setDir(x, y) {
    if (!started) { startOrRestart(); }
    if (dead) return;
    if (queue.length < 2) queue.push({x:x,y:y});
    if (paused) togglePause();
  }
  function togglePause() {
    if (!started || dead) return;
    paused = !paused;
    elPause.setAttribute("opacity", paused ? "1" : "0");
    if (!paused) loop();
  }
  document.addEventListener("keydown", function (e) {
    var k = e.key;
    if (k==="ArrowUp"||k==="w"||k==="W") { setDir(0,-1); e.preventDefault(); }
    else if (k==="ArrowDown"||k==="s"||k==="S") { setDir(0,1); e.preventDefault(); }
    else if (k==="ArrowLeft"||k==="a"||k==="A") { setDir(-1,0); e.preventDefault(); }
    else if (k==="ArrowRight"||k==="d"||k==="D") { setDir(1,0); e.preventDefault(); }
    else if (k===" "||k==="Enter") {
      e.preventDefault();
      if (!started || dead) startOrRestart(); else togglePause();
    }
  });
  var tx = 0, ty = 0;
  document.addEventListener("touchstart", function (e) { tx = e.touches[0].clientX; ty = e.touches[0].clientY; }, {passive: true});
  document.addEventListener("touchend", function (e) {
    var dx = e.changedTouches[0].clientX - tx, dy = e.changedTouches[0].clientY - ty;
    if (Math.abs(dx) > Math.abs(dy)) { if (Math.abs(dx) > 20) setDir(dx>0?1:-1, 0); }
    else if (Math.abs(dy) > 20) setDir(0, dy>0?1:-1);
  }, {passive: true});
  document.addEventListener("click", function () { if (!started || dead) startOrRestart(); });
  reset();
})();
